begin;
select no_plan();
insert into auth.users(id,aud,role,email,email_confirmed_at)
select ('85000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'authenticated','authenticated',
 'resource-feedback-'||n||'@example.test',case when n=6 then null else now() end from generate_series(1,8) n;
insert into public.staff_roles(user_id,role) values
 ('85000000-0000-4000-8000-000000000003','admin'),
 ('85000000-0000-4000-8000-000000000004','super_admin'),
 ('85000000-0000-4000-8000-000000000005','membership_reviewer');
create function pg_temp.feedback(p_body text default 'Please verify the published actuator mass.',p_key uuid default gen_random_uuid(),p_document text default 'robotic-actuators-white-paper') returns jsonb
language sql as $$ select public.submit_resource_feedback(p_document,'correction','Section 3',p_body,'https://example.test/datasheet','Research reader','2026-10-25-resource-feedback-v1',p_key); $$;
select ok((select relrowsecurity from pg_class where oid='private.resource_feedback'::regclass),'feedback table has RLS');
select ok((select relrowsecurity from pg_class where oid='private.resource_feedback_history'::regclass),'feedback history has RLS');
select ok(not has_table_privilege('authenticated','private.resource_feedback','SELECT,INSERT,UPDATE,DELETE'),'direct member table access revoked');
select ok(not has_table_privilege('anon','private.resource_feedback_history','SELECT'),'anonymous history access revoked');
select ok(not has_function_privilege('authenticated','private.resource_feedback_moderator()','EXECUTE'),'private authorization helper not exposed');
set local role anon;
select set_config('request.jwt.claim.sub','',true);
select is(public.resource_feedback_access(),' {"can_submit":false,"can_moderate":false}'::jsonb,'anonymous access is read only');
select is(public.list_resource_feedback('robotic-actuators-white-paper')->>'total','0','public list initially empty');
select throws_ok($$select public.list_my_resource_feedback('robotic-actuators-white-paper')$$,'42501',null,'anonymous own list denied');
select throws_ok($$select pg_temp.feedback()$$,'42501',null,'anonymous submission denied');
select throws_ok($$select public.list_resource_feedback('unknown')$$,'22023',null,'unknown document denied');
select throws_ok($$select public.list_resource_feedback('actuator-specifications',0)$$,'22023',null,'invalid page denied');
set local role authenticated;
select set_config('request.jwt.claim.sub','85000000-0000-4000-8000-000000000006',true);
select is(public.resource_feedback_access()->>'can_submit','false','unconfirmed email not Basic');
select throws_ok($$select pg_temp.feedback()$$,'42501',null,'unconfirmed account cannot submit');
select set_config('request.jwt.claim.sub','85000000-0000-4000-8000-000000000001',true);
select is(public.resource_feedback_access(),' {"can_submit":true,"can_moderate":false}'::jsonb,'confirmed email may contribute without ID or mobile');
select set_config('test.feedback_id',pg_temp.feedback(p_key=>'85000000-0000-4000-8001-000000000001')->>'id',true);
select is(public.list_my_resource_feedback('robotic-actuators-white-paper')->>'total','1','author sees pending feedback');
select is(public.list_my_resource_feedback('robotic-actuators-white-paper')->'items'->0->>'status','pending','new contribution waits for approval');
select is(pg_temp.feedback(p_key=>'85000000-0000-4000-8001-000000000001')->>'id',current_setting('test.feedback_id'),'identical retry returns same receipt');
select throws_ok($$select pg_temp.feedback('Changed payload','85000000-0000-4000-8001-000000000001')$$,'P0409',null,'idempotency key bound to content');
select throws_ok($$select pg_temp.feedback(p_key=>'85000000-0000-4000-8001-000000000001',p_document=>'actuator-specifications')$$,'P0409',null,'idempotency key bound to document');
select throws_ok($$select pg_temp.feedback(repeat('x',4001))$$,'22023',null,'oversized comment denied');
select throws_ok($$select public.submit_resource_feedback('actuator-specifications','comment','','body','javascript:alert(1)','Reader','2026-10-25-resource-feedback-v1',gen_random_uuid())$$,'22023',null,'unsafe source scheme denied');
select throws_ok($$select public.submit_resource_feedback('actuator-specifications','comment','','body',null,'Reader','wrong-consent',gen_random_uuid())$$,'22023',null,'explicit publication consent required');
select throws_ok($$select public.submit_resource_feedback('actuator-specifications','comment','','body',null,' ','2026-10-25-resource-feedback-v1',gen_random_uuid())$$,'22023',null,'public display name required');
select throws_ok($$select public.list_resource_feedback_queue()$$,'42501',null,'ordinary member cannot read moderation queue');
select throws_ok($$select public.review_resource_feedback(current_setting('test.feedback_id')::uuid,1,'approved','','')$$,'42501',null,'ordinary member cannot moderate');
select throws_ok($$select * from private.resource_feedback$$,'42501',null,'RPC access does not expose private table');
select set_config('request.jwt.claim.sub','85000000-0000-4000-8000-000000000002',true);
select is(public.list_my_resource_feedback('robotic-actuators-white-paper')->>'total','0','other member cannot see pending feedback');
select throws_ok($$select public.withdraw_resource_feedback(current_setting('test.feedback_id')::uuid,1)$$,'42501',null,'other member cannot withdraw feedback');
select set_config('request.jwt.claim.sub','85000000-0000-4000-8000-000000000005',true);
select is(public.resource_feedback_access()->>'can_moderate','false','membership-review Staff are not moderators');
select throws_ok($$select public.list_resource_feedback_queue()$$,'42501',null,'membership-review Staff cannot read queue');
select throws_ok($$select public.review_resource_feedback(current_setting('test.feedback_id')::uuid,1,'approved','','')$$,'42501',null,'membership-review Staff cannot approve');
set local role anon;
select set_config('request.jwt.claim.sub','',true);
select is(public.list_resource_feedback('robotic-actuators-white-paper')->>'total','0','pending feedback remains private');
set local role authenticated;
select set_config('request.jwt.claim.sub','85000000-0000-4000-8000-000000000003',true);
select is(public.resource_feedback_access()->>'can_moderate','true','active admin can moderate');
select is(public.list_resource_feedback_queue()->>'total','1','admin sees pending queue');
select throws_ok($$select public.list_resource_feedback_queue('unknown')$$,'22023',null,'queue rejects invalid status');
select throws_ok($$select public.review_resource_feedback(current_setting('test.feedback_id')::uuid,1,'rejected','','')$$,'22023',null,'rejection requires author-visible reason');
select is(public.review_resource_feedback(current_setting('test.feedback_id')::uuid,1,'approved','Thank you; we will verify the source.','Reviewed for publication')->>'revision','2','approval increments revision');
select throws_ok($$select public.review_resource_feedback(current_setting('test.feedback_id')::uuid,1,'rejected','','Stale action')$$,'P0409',null,'stale moderator action denied');
set local role anon;
select set_config('request.jwt.claim.sub','',true);
select is(public.list_resource_feedback('robotic-actuators-white-paper')->>'total','1','approved feedback publicly readable');
select is(public.list_resource_feedback('actuator-specifications')->>'total','0','document threads stay separate');
select ok(not ((public.list_resource_feedback('robotic-actuators-white-paper')->'items'->0) ?| array['author_id','request_id','email','review_note','status','reviewer_id','consent_version']),'public projection excludes private identity and moderation fields');
select is(public.list_resource_feedback('robotic-actuators-white-paper')->'items'->0->>'display_name','Research reader','only explicitly chosen name displayed');
select is(public.list_resource_feedback('robotic-actuators-white-paper')->'items'->0->>'response','Thank you; we will verify the source.','public moderator response is included');
set local role authenticated;
select set_config('request.jwt.claim.sub','85000000-0000-4000-8000-000000000001',true);
select is(public.list_my_resource_feedback('robotic-actuators-white-paper')->'items'->0->>'review_note','Reviewed for publication','author sees review note');
select throws_ok($$select public.withdraw_resource_feedback(current_setting('test.feedback_id')::uuid,1)$$,'P0409',null,'stale author withdrawal denied');
reset role;
insert into public.basic_onboarding_applications(user_id,full_name,email,phone,linkedin_url,date_of_birth,status)
values('85000000-0000-4000-8000-000000000001','Private full name','resource-feedback-1@example.test','+919000000001','https://linkedin.com/in/synthetic-feedback','1990-01-01','revoked');
set local role anon;
select set_config('request.jwt.claim.sub','',true);
select is(public.list_resource_feedback('robotic-actuators-white-paper')->>'total','0','revoked author no longer appears publicly');
set local role authenticated;
select set_config('request.jwt.claim.sub','85000000-0000-4000-8000-000000000001',true);
select is(public.resource_feedback_access()->>'can_submit','false','revoked account cannot contribute');
select throws_ok($$select pg_temp.feedback()$$,'42501',null,'revoked submission denied');
select is(public.list_my_resource_feedback('robotic-actuators-white-paper')->>'total','1','revoked author can still read own feedback');
select is(public.withdraw_resource_feedback(current_setting('test.feedback_id')::uuid,2)->>'status','withdrawn','revoked author may withdraw');
select is(public.withdraw_resource_feedback(current_setting('test.feedback_id')::uuid,3)->>'revision','3','repeated withdrawal has no extra revision');
select set_config('request.jwt.claim.sub','85000000-0000-4000-8000-000000000004',true);
select is(public.resource_feedback_access()->>'can_moderate','true','super admin can moderate');
select throws_ok($$select public.review_resource_feedback(current_setting('test.feedback_id')::uuid,3,'approved','','')$$,'P0409',null,'withdrawn feedback cannot be republished');
select set_config('request.jwt.claim.sub','85000000-0000-4000-8000-000000000002',true);
select set_config('test.rejected_id',pg_temp.feedback(p_document=>'actuator-specifications')->>'id',true);
select set_config('request.jwt.claim.sub','85000000-0000-4000-8000-000000000004',true);
select is(public.review_resource_feedback(current_setting('test.rejected_id')::uuid,1,'rejected','','Please provide the matching revision datasheet.')->>'status','rejected','super admin can reject with a reason');
select set_config('request.jwt.claim.sub','85000000-0000-4000-8000-000000000002',true);
select is(public.list_my_resource_feedback('actuator-specifications')->'items'->0->>'review_note','Please provide the matching revision datasheet.','rejected author sees actionable review note');
set local role anon;
select set_config('request.jwt.claim.sub','',true);
select is(public.list_resource_feedback('actuator-specifications')->>'total','0','rejected feedback and review note remain private');
set local role authenticated;
select set_config('request.jwt.claim.sub','85000000-0000-4000-8000-000000000004',true);
select is(public.list_resource_feedback_queue('all')->>'total','2','all queue includes rejected and author-withdrawn feedback');
select throws_ok($$select public.review_resource_feedback(current_setting('test.rejected_id')::uuid,2,'withdrawn','','')$$,'22023',null,'admin withdrawal requires a note');
select is(public.review_resource_feedback(current_setting('test.rejected_id')::uuid,2,'withdrawn','','Removed at editorial review.')->>'status','withdrawn','admin may withdraw feedback with an explanation');
select throws_ok($$select public.review_resource_feedback(current_setting('test.rejected_id')::uuid,3,'approved','','')$$,'P0409',null,'admin-withdrawn feedback is terminal too');
select set_config('request.jwt.claim.sub','85000000-0000-4000-8000-000000000002',true);
select is(public.list_my_resource_feedback('actuator-specifications')->'items'->0->>'review_note','Removed at editorial review.','author sees admin withdrawal explanation');
reset role;
update auth.users set banned_until=now()+interval '1 day' where id='85000000-0000-4000-8000-000000000003';
set local role authenticated;
select set_config('request.jwt.claim.sub','85000000-0000-4000-8000-000000000003',true);
select is(public.resource_feedback_access()->>'can_moderate','false','banned admin cannot moderate with old JWT');
select throws_ok($$select public.list_resource_feedback_queue()$$,'42501',null,'banned admin queue access denied');
reset role;
insert into public.memberships(user_id,status) values('85000000-0000-4000-8000-000000000002','suspended') on conflict(user_id) do update set status='suspended';
set local role authenticated;
select set_config('request.jwt.claim.sub','85000000-0000-4000-8000-000000000002',true);
select throws_ok($$select pg_temp.feedback()$$,'42501',null,'suspended membership cannot submit');
select set_config('request.jwt.claim.sub','85000000-0000-4000-8000-000000000007',true);
select set_config('test.hourly_id',pg_temp.feedback(p_key=>'85000000-0000-4000-8002-000000000001')->>'id',true);
select pg_temp.feedback('Hourly entry '||n) from generate_series(2,5) n;
select throws_ok($$select pg_temp.feedback('Sixth hourly submission')$$,'P0429',null,'sixth hourly contribution denied');
select is(pg_temp.feedback(p_key=>'85000000-0000-4000-8002-000000000001')->>'id',current_setting('test.hourly_id'),'retry returns receipt even at rate limit');
reset role;
insert into private.resource_feedback(author_id,request_id,document,kind,body,display_name,consent_version,created_at)
select '85000000-0000-4000-8000-000000000008',gen_random_uuid(),'actuator-specifications','comment','Earlier daily entry '||n,'Reader','2026-10-25-resource-feedback-v1',now()-interval '2 hours' from generate_series(1,20) n;
set local role authenticated;
select set_config('request.jwt.claim.sub','85000000-0000-4000-8000-000000000008',true);
select throws_ok($$select pg_temp.feedback('Twenty-first daily submission')$$,'P0429',null,'daily rate limit spans both document threads');
select is(jsonb_array_length(public.list_my_resource_feedback('actuator-specifications')->'items'),20,'own list bounded to twenty entries');
select is(jsonb_array_length(public.list_my_resource_feedback('actuator-specifications',2)->'items'),0,'next page does not repeat entries');
reset role;
select is((select count(*)::integer from private.resource_feedback_history where feedback_id=current_setting('test.feedback_id')::uuid),3,'submission, approval and withdrawal are audited once');
select is((select count(*)::integer from private.resource_feedback where author_id='85000000-0000-4000-8000-000000000007'),5,'hourly failure and retry create no extra rows');
select * from finish();
rollback;
